function N(t){const n=Math.max(0,Math.min(100,Number(t)||0));return Math.round(5e7+25e6*(n/100))}function M(t){const n=Math.max(0,Math.min(100,Number(t)||50));return Math.round(70+n*.3)}function p(t){let n=0;for(const a of t||[])n+=Math.round(Number(a.purchase_price||0)*(Number(a.condition||0)/100));return n}function h(t,n){let a=0;const u=Number(n||0);for(const o of t||[]){if(o.status==="for_sale")continue;const e=Math.max(0,Math.floor((u-Number(o.built_at_tick||0))/12)),r=Math.max(.2,1-.05*e),c=Number(o.condition||0)/100;a+=Math.round(Number(o.purchase_price||0)*r*c)}return a}function f({cash:t,loans:n,properties:a,propertyValue:u,vessels:o,equipmentValue:e,financeReceivables:r,currentTick:c}){const i=u!=null?Number(u):p(a),s=e!=null?Number(e):h(o,c),l=Math.max(0,Number(r||0)),m=Number(n||0),b=Number(t||0)+i+s+l-m;return{cash:Number(t||0),propertyValue:i,equipmentValue:s,financeReceivables:l,liabilities:m,valuationBasis:b,valuation:Math.round(b*1.3)}}function d({cash:t,loans:n,properties:a,propertyValue:u,vessels:o,equipmentValue:e,financeReceivables:r,currentTick:c}){return f({cash:t,loans:n,properties:a,propertyValue:u,vessels:o,equipmentValue:e,financeReceivables:r,currentTick:c}).valuation}export{h as a,M as b,d as c,N as n};
